python3 -c "
items = {
    'Item2': {
        'core_conclusion': 'vLLM 0.25.0通过Mooncake连接器支持GDN与MLA格式的Prefill/Decode解耦，但未提供网络感知调度或性能指标。',
        'mechanism': '集成Mooncake连接器支持GDN与MLA模型，加NIXL Mamba1与多连接KV合并。',
        'result': '实现计算阶段解耦但发布未公开TTFT/TPOT改善、网络利用率或KVCache传输开销。',
        'boundary': '缺网络侧调度与KV位置感知，Mooncake性能未公开。',
        'project_relevance': '仅传输集成未现TTFT/TPOT优化或网络调度，对TPN网络感知价值有限。'
    },
    'Item3': {
        'core_conclusion': 'ExpertPlex通过混合解耦-同驻架构在MoE模型上实现2.01倍Goodput提升，同时阶段间共享超95%专家权重。',
        'mechanism': '跨阶段共享MoE专家并解耦注意力模块，用自适应持久内核以Tile粒度调度动态专家计算。',
        'result': '相对SGLang-PDD Goodput 2.01倍，相对PDMux 1.41倍。',
        'boundary': 'PDD基线对GLM-5.1-FP8未报告，集群完整验证未公开。',
        'project_relevance': 'Attention单边MoE通信减跨阶段干扰，定TTFT/TPOT SLO但网络利用与KV感知不全。'
    }
}

for item_name, fields in items.items():
    total = sum(len(v) for v in fields.values())
    print(f'{item_name}: {total} chars')
    for k, v in fields.items():
        print(f'  {k}: {len(v)}')
    print()
"
